import sys, json

class Solution:
    def findGoodStrings(self, n: int, s1: str, s2: str, evil: str) -> int:
        MOD = 1_000_000_007
        m = len(evil)

        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and evil[i] != evil[j]:
                j = pi[j - 1]
            if evil[i] == evil[j]:
                j += 1
            pi[i] = j

        nxt = [[0] * 26 for _ in range(m)]
        for state in range(m):
            for c in range(26):
                ch = chr(97 + c)
                j = state
                while j > 0 and evil[j] != ch:
                    j = pi[j - 1]
                if evil[j] == ch:
                    j += 1
                nxt[state][c] = j

        def count_leq(bound: str) -> int:
            dp = [[0] * m for _ in range(2)]
            dp[1][0] = 1
            for ch in bound:
                ndp = [[0] * m for _ in range(2)]
                limit = ord(ch) - 97
                for tight in range(2):
                    hi = limit if tight else 25
                    for state in range(m):
                        ways = dp[tight][state]
                        if not ways:
                            continue
                        for c in range(hi + 1):
                            ns = nxt[state][c]
                            if ns == m:
                                continue
                            nt = 1 if tight and c == limit else 0
                            ndp[nt][ns] = (ndp[nt][ns] + ways) % MOD
                dp = ndp
            return sum(map(sum, dp)) % MOD

        # count(s1 <= x <= s2) = count(x <= s2) - count(x < s1)
        less_than_s1 = count_leq(s1)
        state = 0
        contains = False
        for ch in s1:
            state = nxt[state][ord(ch) - 97]
            if state == m:
                contains = True
                break
        if not contains:
            less_than_s1 = (less_than_s1 - 1) % MOD

        return (count_leq(s2) - less_than_s1) % MOD

