#include <stdio.h>
#include <string.h>

#define MOD 1000000007LL

static int next_state[50][26];

int findGoodStrings(int n, const char *s1, const char *s2, const char *evil) {
    int m = (int)strlen(evil);
    int pi[50] = {0};

    for (int i = 1; i < m; ++i) {
        int j = pi[i - 1];
        while (j > 0 && evil[i] != evil[j]) j = pi[j - 1];
        if (evil[i] == evil[j]) ++j;
        pi[i] = j;
    }

    for (int state = 0; state < m; ++state) {
        for (int c = 0; c < 26; ++c) {
            char ch = (char)('a' + c);
            int j = state;
            while (j > 0 && evil[j] != ch) j = pi[j - 1];
            if (evil[j] == ch) ++j;
            next_state[state][c] = j;
        }
    }

    long long dp[2][50] = {{0}}, ndp[2][50];
    long long count_s1 = 0, count_s2 = 0;

    const char *bounds[2] = {s1, s2};
    long long *results[2] = {&count_s1, &count_s2};

    for (int b = 0; b < 2; ++b) {
        memset(dp, 0, sizeof(dp));
        dp[1][0] = 1;

        for (int i = 0; i < n; ++i) {
            memset(ndp, 0, sizeof(ndp));
            int limit = bounds[b][i] - 'a';
            for (int tight = 0; tight < 2; ++tight) {
                int hi = tight ? limit : 25;
                for (int state = 0; state < m; ++state) {
                    long long ways = dp[tight][state];
                    if (!ways) continue;
                    for (int c = 0; c <= hi; ++c) {
                        int ns = next_state[state][c];
                        if (ns == m) continue;
                        int nt = (tight && c == limit) ? 1 : 0;
                        ndp[nt][ns] = (ndp[nt][ns] + ways) % MOD;
                    }
                }
            }
            memcpy(dp, ndp, sizeof(dp));
        }

        long long total = 0;
        for (int tight = 0; tight < 2; ++tight)
            for (int state = 0; state < m; ++state)
                total = (total + dp[tight][state]) % MOD;
        *results[b] = total;
    }

    int state = 0;
    int contains = 0;
    for (int i = 0; i < n; ++i) {
        state = next_state[state][s1[i] - 'a'];
        if (state == m) {
            contains = 1;
            break;
        }
    }

    long long less_s1 = count_s1;
    if (!contains) {
        less_s1 = (less_s1 - 1 + MOD) % MOD;
    }

    return (int)((count_s2 - less_s1 + MOD) % MOD);
}

int main(void) {
    char line[1200];
    int n;
    char s1[501], s2[501], evil[51];

    if (!fgets(line, sizeof(line), stdin)) return 1;
    if (sscanf(line, "[%d,\"%500[^\"]\",\"%500[^\"]\",\"%50[^\"]\"]", &n, s1, s2, evil) != 4)
        return 1;

    printf("%d\n", findGoodStrings(n, s1, s2, evil));
    return 0;
}

