import java.io.*;
import java.util.*;

class Solution {
    private static final int MOD = 1_000_000_007;

    public int findGoodStrings(int n, String s1, String s2, String evil) {
        int m = evil.length();

        int[] pi = new int[m];
        for (int i = 1; i < m; i++) {
            int j = pi[i - 1];
            while (j > 0 && evil.charAt(i) != evil.charAt(j)) j = pi[j - 1];
            if (evil.charAt(i) == evil.charAt(j)) j++;
            pi[i] = j;
        }

        int[][] next = new int[m][26];
        for (int state = 0; state < m; state++) {
            for (int c = 0; c < 26; c++) {
                char ch = (char)('a' + c);
                int j = state;
                while (j > 0 && evil.charAt(j) != ch) j = pi[j - 1];
                if (evil.charAt(j) == ch) j++;
                next[state][c] = j;
            }
        }

        long countS2 = countLE(s2, next, m);
        long countS1 = countLE(s1, next, m);

        int state = 0;
        boolean contains = false;
        for (int i = 0; i < n; i++) {
            state = next[state][s1.charAt(i) - 'a'];
            if (state == m) {
                contains = true;
                break;
            }
        }
        long lessThanS1 = countS1 - (contains ? 0 : 1);
        lessThanS1 %= MOD;
        if (lessThanS1 < 0) lessThanS1 += MOD;

        return (int)((countS2 - lessThanS1 + MOD) % MOD);
    }

    private long countLE(String bound, int[][] next, int m) {
        long[][] dp = new long[2][m];
        dp[1][0] = 1;

        for (int i = 0; i < bound.length(); i++) {
            long[][] ndp = new long[2][m];
            int limit = bound.charAt(i) - 'a';
            for (int tight = 0; tight < 2; tight++) {
                int hi = tight == 1 ? limit : 25;
                for (int state = 0; state < m; state++) {
                    long ways = dp[tight][state];
                    if (ways == 0) continue;
                    for (int c = 0; c <= hi; c++) {
                        int ns = next[state][c];
                        if (ns == m) continue;
                        int nt = (tight == 1 && c == limit) ? 1 : 0;
                        ndp[nt][ns] = (ndp[nt][ns] + ways) % MOD;
                    }
                }
            }
            dp = ndp;
        }

        long total = 0;
        for (int tight = 0; tight < 2; tight++)
            for (int state = 0; state < m; state++)
                total = (total + dp[tight][state]) % MOD;
        return total;
    }
}

public class Main {
    static String[] parse(String line) {
        ArrayList<String> parts = new ArrayList<>();
        int i = 0;
        while (i < line.length()) {
            while (i < line.length() && (line.charAt(i) == '[' || line.charAt(i) == ']' ||
                    line.charAt(i) == ',' || Character.isWhitespace(line.charAt(i)))) i++;
            if (i >= line.length()) break;
            if (line.charAt(i) == '"') {
                int j = i + 1;
                while (j < line.length() && line.charAt(j) != '"') j++;
                parts.add(line.substring(i + 1, j));
                i = j + 1;
            } else {
                int j = i;
                while (j < line.length() && line.charAt(j) != ',' && line.charAt(j) != ']') j++;
                parts.add(line.substring(i, j).trim());
                i = j;
            }
        }
        return parts.toArray(new String[0]);
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] p = parse(br.readLine());
        int n = Integer.parseInt(p[0]);
        String s1 = p[1], s2 = p[2], evil = p[3];
        System.out.println(new Solution().findGoodStrings(n, s1, s2, evil));
    }
}

